WITH cleaned AS (SELECT id, account_type, opened_date, status, TRIM(status) AS clean_status, TRIM(status) AS clean_status_2, COALESCE(status, 'NONE') AS status_clean FROM accounts WHERE status IS NOT NULL AND account_type IN ('CREDIT', 'LOAN', 'CHECKING')), not_flagged AS (SELECT s.* FROM cleaned s WHERE NOT EXISTS (SELECT 1 FROM transactions ch WHERE ch.account_id = s.id AND ch.txn_time <= s.opened_date)), with_windows AS (SELECT id, opened_date, status, clean_status_2, status_clean, FIRST_VALUE(status, TRUE) OVER w_part AS first_known_status, ROW_NUMBER() OVER (ORDER BY opened_date DESC, id) AS seq_no, FIRST_VALUE(status) IGNORE NULLS OVER w_part AS first_known_status_2, LAST_VALUE(status) IGNORE NULLS OVER w_part AS last_known_status, LAST_VALUE(status) IGNORE NULLS OVER (ORDER BY opened_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_status_2 FROM not_flagged WHERE account_type IN ('CHECKING', 'CREDIT', 'LOAN') WINDOW w_part AS (PARTITION BY account_type ORDER BY opened_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)), metrics AS (SELECT *, AVG(seq_no) OVER w_recent AS running_avg_seq_no, MAX(seq_no) OVER w_recent AS running_max_seq_no, MIN(seq_no) OVER w_recent AS running_min_seq_no, SUM(seq_no) OVER w_recent AS running_sum_seq_no, SUM(seq_no) OVER w_running AS status_sum_seq_no FROM with_windows WINDOW w_recent AS (PARTITION BY status ORDER BY seq_no, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW), w_running AS (PARTITION BY status)) SELECT id, opened_date, status, clean_status_2, status_clean, last_known_status, running_max_seq_no, running_sum_seq_no, LEAD(running_avg_seq_no, 1, 0) OVER (PARTITION BY status ORDER BY running_min_seq_no, id) AS next_running_avg_seq_no, FIRST_VALUE(running_min_seq_no, TRUE) OVER (ORDER BY opened_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_running_min_seq_no FROM metrics
